                                                                                                                                                                                                                 
  CREATE TABLE "SYSTEM_UPDATE_LOG"                                                                                                                                                                    
   (	"UPDATE_LOG_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                      
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                           
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                      
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                             
	"VERSION" NVARCHAR2(50) NOT NULL ENABLE,                                                                                                                                                                        
	"UPDATE_CONTENT" CLOB NOT NULL ENABLE,                                                                                                                                                                          
	"PUBLISH_DATE" NVARCHAR2(50) NOT NULL ENABLE,                                                                                                                                                                   
	"TENANT_ID" NUMBER(20,0) DEFAULT 3,                                                                                                                                                                             
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                                   
	 PRIMARY KEY ("UPDATE_LOG_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                            
   ) ;                                                                                                                                                                                                           

